91: async function loadMorePosts() {
92:     const loader = document.getElementById('loading-indicator');
93:     if (loader) loader.classList.remove('hidden');
94: 
95:     const sort = feedConfig.sort || 'desc';
96:     const date = feedConfig.date || '';
97:     const profileId = feedConfig.profile_id || '';
98: 
99:     const url = `api/feed.php?type=${currentFeedType}&sort=${sort}&date=${date}&profile_id=${profileId}&seen=${seenIds.join(',')}&_t=${Date.now()}`;
100:     const res = await fetch(url, { cache: 'no-store' }).then(r => r.json());
101: 
102:     if (loader) loader.classList.add('hidden');
103: 
104:     if (res.success && res.posts.length > 0) {
105:         preloadedPosts.push(...res.posts);
106:         res.posts.forEach(p => {
107:             seenIds.push(p.id);
108:             if (parseInt(p.id) > highestSeenPostId) {
109:                 highestSeenPostId = parseInt(p.id);
110:             }
111:         });
112:         return true;
113:     } else {
114:         if (feedConfig.loop && seenIds.length > 0) {
115:             seenIds = [];
116:             return await loadMorePosts();
117:         }
118:         return false;
119:     }
120: }
