330:         card.classList.add('single-post-card', 'relative', 'my-4');
331:     }
332:     card.dataset.id = post.id;
333:     card.dataset.userId = post.user_id;
334:     card.style.zIndex = 10;
335:     card.postData = post;
336: 
337:     let isOwner = post.user_id == window.CURRENT_USER_ID;
338:     let isAdmin = window.CURRENT_ROLE === 'admin';
339: 
340:     const urlParams = new URLSearchParams(window.location.search);
341:     const isPostPage = window.location.pathname.endsWith('post.php');
342:     const isSinglePostView = isPostPage && urlParams.get('h') === post.post_hash;
343: 
344:     let displayContent = post.text_content || '';
345:     
346:     let linkPreviewHtml = '';
347:     let extractedUrl = '';
348:     
349:     if (!post.image_url && displayContent) {
350:         const urlRegex = /\b(?:https?:\/\/|www\.)[-a-zA-Z0-9+&@#\/%?=~_|!:,.;]*[-a-zA-Z0-9+&@#\/%=~_|]|\b[-a-zA-Z0-9+&@#\/%?=~_|!:,.;]+\.[a-zA-Z]{2,}\b[-a-zA-Z0-9+&@#\/%?=~_|!:,.;]*/gi;
351:         const matches = displayContent.match(urlRegex);
352:         if (matches) {
353:             for (let m of matches) {
354:                 if (m.includes('@') && !/^(?:f|ht)tps?:\/\//i.test(m)) continue;
355:                 if (/\.(php|html|css|js|log|json|xml|sql|exe|dll)$/i.test(m)) continue;
356:                 extractedUrl = m;
357:                 break;
358:             }
359:         }
360:     }
361: 
362:     if (!isSingleView && displayContent) {
363:         const limit = post.image_url ? 150 : 200;
364:         const maxLines = post.image_url ? 3 : 5;
365: 
366:         let needsTruncation = false;
367:         let truncated = displayContent;
368: 
369:         if (truncated.length > limit) {
370:             needsTruncation = true;
371:             truncated = truncated.substring(0, limit);
372:             const lastSpace = truncated.lastIndexOf(' ');
373:             if (lastSpace > 0) truncated = truncated.substring(0, lastSpace);
374:         }
375: 
376:         const lines = truncated.split(/<br\s*\/?>/i);
377:         if (lines.length > maxLines) {
378:             needsTruncation = true;
379:             truncated = lines.slice(0, maxLines).join('<br />');
380:         }
381: 
382:         if (needsTruncation) {
383:             displayContent = `${truncated}... <span class="text-blue-500 font-medium hover:underline">show more</span>`;
384:         }
385:     }
386: 
387:     if (extractedUrl) {
388:         let href = extractedUrl;
389:         if (!/^(?:f|ht)tps?:\/\//i.test(href)) {
390:             href = 'http://' + href;
391:         }
392:         
393:         // Only replace if it's still fully intact in the truncated text
394:         const safeRegex = new RegExp(extractedUrl.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
395:         if (safeRegex.test(displayContent)) {
396:              displayContent = displayContent.replace(safeRegex, `<a href="out.php?url=${encodeURIComponent(href)}" onclick="window.event?.stopPropagation();" class="text-blue-500 transition">${extractedUrl}</a>`);
397:         }
398: 
399:         linkPreviewHtml = `
