411: 
412:     // For single view, we use the original sizing. For swipe feed, we use a flex container that shrinks the image to fit available card space.
413:     const imgWrapperClass = isSinglePostView
414:         ? 'px-4 pb-4'
415:         : 'px-4 pb-4 flex-1 min-h-[100px] flex flex-col overflow-hidden';
