626:         const currentEventX = e.type.includes('mouse') ? e.pageX : e.touches[0].pageX;
627:         const currentEventY = e.type.includes('mouse') ? e.pageY : e.touches[0].pageY;
628: 
629:         if (isHorizontalSwipe === null) {
630:             const diffX = Math.abs(currentEventX - startX);
