283: function timeSince(dateString) {
284:     let parsedString = dateString;
285:     if (!parsedString.includes('T')) parsedString = parsedString.replace(' ', 'T') + 'Z';
286:     const date = new Date(parsedString);
287:     const seconds = Math.floor((new Date() - date) / 1000);
288: 
289:     if (seconds > 3 * 86400) {
290:         return date.toLocaleDateString('en-US', {
291:             month: 'short',
292:             day: 'numeric',
293:             year: 'numeric'
294:         }) + ' at ' + date.toLocaleTimeString('en-US', {
295:             hour: 'numeric',
296:             minute: '2-digit'
297:         });
298:     }
299: 
300:     let interval = seconds / 86400;
301:     if (interval >= 1) return Math.floor(interval) + (Math.floor(interval) === 1 ? " day ago" : " days ago");
302:     interval = seconds / 3600;
303:     if (interval >= 1) return Math.floor(interval) + (Math.floor(interval) === 1 ? " hour ago" : " hours ago");
304:     interval = seconds / 60;
305:     if (interval >= 1) return Math.floor(interval) + (Math.floor(interval) === 1 ? " minute ago" : " minutes ago");
306: 
307:     const s = Math.max(0, Math.floor(seconds));
308:     return s + (s === 1 ? " second ago" : " seconds ago");
309: }
