294: function timeSince(dateString) {
295:     let parsedString = dateString;
296:     if (!parsedString.includes('T')) parsedString = parsedString.replace(' ', 'T') + 'Z';
297:     const date = new Date(parsedString);
298:     const seconds = Math.floor((new Date() - date) / 1000);
299: 
300:     if (seconds > 3 * 86400) {
301:         return date.toLocaleDateString('en-US', {
302:             month: 'short',
303:             day: 'numeric',
304:             year: 'numeric'
305:         }) + ' at ' + date.toLocaleTimeString('en-US', {
306:             hour: 'numeric',
307:             minute: '2-digit'
308:         });
309:     }
310: 
311:     let interval = seconds / 86400;
312:     if (interval >= 1) return Math.floor(interval) + (Math.floor(interval) === 1 ? " day ago" : " days ago");
313:     interval = seconds / 3600;
314:     if (interval >= 1) return Math.floor(interval) + (Math.floor(interval) === 1 ? " hour ago" : " hours ago");
315:     interval = seconds / 60;
316:     if (interval >= 1) return Math.floor(interval) + (Math.floor(interval) === 1 ? " minute ago" : " minutes ago");
317: 
318:     const s = Math.max(0, Math.floor(seconds));
319:     return s + (s === 1 ? " second ago" : " seconds ago");
320: }
