597: function setupSwipe(card) {
598:     if (card.style.position === 'relative') {
599:         return;
600:     }
601:     let startX = 0;
602:     let startY = 0;
603:     let currentX = 0;
604:     let isDragging = false;
605:     let isHorizontalSwipe = null;
606: 
607:     function ignoreSwipe(e) {
608:         if (e.target.closest('.comments-section') || e.target.closest('.dropdown-menu') || e.target.closest('button') || e.target.closest('input')) {
609:             return true;
610:         }
611:         return false;
612:     }
613: 
614:     const startDrag = (e) => {
615:         if (ignoreSwipe(e)) return;
616:         isDragging = true;
617:         startX = e.type.includes('mouse') ? e.pageX : e.touches[0].pageX;
618:         startY = e.type.includes('mouse') ? e.pageY : e.touches[0].pageY;
619:         currentX = startX;
620:         isHorizontalSwipe = null;
621:         card.style.transition = 'none';
622:     };
623: 
624:     const drag = (e) => {
625:         if (!isDragging) return;
626:         const currentEventX = e.type.includes('mouse') ? e.pageX : e.touches[0].pageX;
627:         const currentEventY = e.type.includes('mouse') ? e.pageY : e.touches[0].pageY;
628: 
629:         if (isHorizontalSwipe === null) {
630:             const diffX = Math.abs(currentEventX - startX);
631:             const diffY = Math.abs(currentEventY - startY);
632:             if (diffX > 5 || diffY > 5) {
633:                 isHorizontalSwipe = diffX > diffY;
634:             }
635:         }
636: 
637:         if (isHorizontalSwipe) {
638:             if (e.cancelable) e.preventDefault(); // lock vertical scroll
639:             currentX = currentEventX;
640:             const diffX = currentX - startX;
641:             card.style.transform = `translateX(${diffX}px) rotate(${diffX * 0.05}deg)`;
642:         } else if (isHorizontalSwipe === false) {
643:             isDragging = false;
644:         }
645:     };
646: 
647:     const endDrag = async (e) => {
648:         if (!isDragging) return;
649:         isDragging = false;
650:         if (isHorizontalSwipe === false) return; // it was a vertical scroll
651: 
652:         const diffX = currentX - startX;
653:         card.style.transition = 'transform 0.3s ease, opacity 0.3s ease';
654: 
655:         if (Math.abs(diffX) > 100) {
656:             isAnimating = true;
657:             const direction = diffX > 0 ? 1000 : -1000;
658:             card.style.transform = `translateX(${direction}px) rotate(${direction * 0.05}deg)`;
659:             card.style.opacity = '0';
660: 
661:             const postId = parseInt(card.dataset.id);
662:             if (!feedConfig.loop) {
663:                 API.recordSwipe(postId);
664:             }
665: 
666:             setTimeout(() => {
667:                 card.remove();
668:                 isAnimating = false;
669:                 showNextPost();
670:             }, 300);
671:         } else {
672:             card.style.transform = `translateX(0px) rotate(0deg)`;
673:         }
674:     };
675: 
676:     card.addEventListener('mousedown', startDrag);
677:     card.addEventListener('mousemove', drag);
678:     window.addEventListener('mouseup', endDrag);
679: 
680:     card.addEventListener('touchstart', startDrag);
681:     card.addEventListener('touchmove', drag);
682:     window.addEventListener('touchend', endDrag);
683: }
